local M = class("FlowerMainControl",LikeOO.OOControlBase)

function M:onEnter()
    M.super.onCreate(self)
end

function M:onHandle(msg , data)
    if msg == 99999 then
        self:closeView()
        self:updateMsg("common_refresh",nil,"parent")
    elseif msg == "btn_openBtn1" then
        self:openViewByIndex(1)
    elseif msg == "btn_openBtn2" then
        self:openViewByIndex(2)
    elseif msg == "btn_openBtn3" then
        self:openViewByIndex(3)
    elseif msg == "btn_openBtn4" then
        self:openViewByIndex(4)
    elseif msg == "explain_btn" then
        -- 提示  
        local flowerData = ConfigManager:getCfgByName("flower_festival")
        local versionData = flowerData[self.m_model.m_version]
        local mainActiveData = self.m_model:getXlsxActivityByOpenId(self.m_model.m_parentOpenId, false)
        self:openView("Pops.CommonHelpPop", { title = Language:getTextByKey(mainActiveData.name), content = Language:getTextByKey(versionData.flower_des) })
    elseif msg == "everyDayrefresh" then
        self.m_model:getNetData("flower_festival", {}, function(response)
            if response then
                if self:activityOverExamine(response) then
                    return
                end
                self.m_model:switchData(response)
                self.m_view:refreshUI()
            end
        end, nil, nil, nil)
        self.m_view:refreshAllRedDot()
    end
end

function M:openViewByIndex(index)
    local configData = self.m_model.m_tabConfig[index]
    local openId = configData.open_id
    local isShowEnter = (index == 2 or index == 4)
    if not self.m_model:isOpenActiveByOpenId(openId, configData.isRechargeAct, isShowEnter) then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("flower_text_0021"), delay_close = 2})
        return
    end
    local params = {openId = openId, version = self.m_model.m_version}
    self:openView(configData.lua_name, params)
end

function M:testOpenByActivityTimer()
    -- 时间不准，直接刷新
    self:updateMsg("common_refresh", nil, "parent")
end

function M:activityOverExamine(response)
    if response["end"] == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView()
        return true
    end
    return false
end

function M:destroy()
    M.super.destroy(self)
end

return M